1	import type { ComponentProps, ElementType, ReactNode } from "react";
2	
3	/* The panel every surface in the product is made of. `interactive` is
4	   separate from `as="a"` on purpose — a card can be clickable without being a
5	   link (a form target, a drawer opener), and only the ones that actually
6	   respond should lift on hover. A card that lifts but does nothing is a lie
7	   the cursor tells. */
8	export function Card({
9	  as: Tag = "div",
10	  interactive = false,
11	  padded = true,
12	  className = "",
13	  children,
14	  ...rest
15	}: {
16	  as?: ElementType;
17	  interactive?: boolean;
18	  padded?: boolean;
19	  className?: string;
20	  children: ReactNode;
21	} & Omit<ComponentProps<"div">, "className" | "children">) {
22	  return (
23	    <Tag
24	      {...rest}
25	      className={[
26	        "rounded-xl border border-hair bg-surface shadow-e1",
27	        padded ? "p-5" : "",
28	        interactive
29	          ? "k-focus transition-[box-shadow,border-color,transform] duration-[var(--t-2)] hover:-translate-y-0.5 hover:border-line-mid hover:shadow-e2"
30	          : "",
31	        className,
32	      ]
33	        .filter(Boolean)
34	        .join(" ")}
35	    >
36	      {children}
37	    </Tag>
38	  );
39	}
40	
41	export function CardHeader({
42	  title,
43	  description,
44	  action,
45	  className = "",
46	}: {
47	  title: ReactNode;
48	  description?: ReactNode;
49	  action?: ReactNode;
50	  className?: string;
51	}) {
52	  return (
53	    <div className={`flex items-start justify-between gap-4 ${className}`}>
54	      <div className="min-w-0">
55	        <h2 className="k-h2 text-ink">{title}</h2>
56	        {description != null && (
57	          <p className="mt-1 text-[0.8125rem] leading-relaxed text-ink-2">{description}</p>
58	        )}
59	      </div>
60	      {action != null && <div className="shrink-0">{action}</div>}
61	    </div>
62	  );
63	}
64	
65	/** A page-level section heading. Distinct from CardHeader: this one sits on
66	    the canvas, not inside a panel, and so carries no background of its own.
67	
68	    `as` exists because this component hardcoded `<h2>`, and seven portal pages
69	    used it as their page title — so those documents began their outline at h2
70	    with no h1 at all. The default stays `"h2"` rather than flipping to `"h1"`:
71	    most pages render this more than once, and a component that silently emits
72	    a second h1 is a worse defect than the one being fixed. The FIRST one on a
73	    page passes `as="h1"`; the rest are genuinely sections. */
74	export function SectionHeader({
75	  title,
76	  description,
77	  action,
78	  as: Heading = "h2",
79	}: {
80	  title: ReactNode;
81	  description?: ReactNode;
82	  action?: ReactNode;
83	  as?: "h1" | "h2";
84	}) {
85	  return (
86	    <div className="mb-4 flex flex-wrap items-end justify-between gap-3">
87	      <div className="min-w-0">
88	        {/* k-h1 is the SIZE token and is unrelated to the tag — a page title
89	            and a section title are set alike here by design. */}
90	        <Heading className="k-h1 text-ink">{title}</Heading>
91	        {description != null && <p className="mt-1 text-sm text-ink-2">{description}</p>}
92	      </div>
93	      {action != null && <div className="shrink-0">{action}</div>}
94	    </div>
95	  );
96	}
