1	@import "tailwindcss";
2	
3	/* Class-based dark mode (".dark" on <html>) so the manual theme toggle can
4	   override the OS preference — Tailwind's dark: classes elsewhere in the
5	   app are unaffected in shape, only in what triggers them. */
6	@custom-variant dark (&:where(.dark, .dark *));
7	
8	:root {
9	  --background: #ffffff;
10	  --foreground: #171717;
11	
12	  /* Kodely brand tokens — ported 1:1 from the approved reference mockup
13	     (scratchpad/kodely.html) so the shipped site and the approved design
14	     don't drift again. */
15	  --ink-2: #605b66;
16	  --faint: #a49fad;
17	  --line: rgba(11, 10, 13, 0.09);
18	  --line-2: rgba(11, 10, 13, 0.045);
19	  --panel: #ffffff;
20	  --accent: #e01b6e;
21	  --glow: rgba(247, 37, 112, 0.13);
22	  --glow-2: rgba(163, 61, 255, 0.12);
23	  --sh-s: 0 1px 2px rgba(11, 10, 13, 0.04), 0 6px 16px -8px rgba(11, 10, 13, 0.1);
24	  --sh: 0 40px 100px -50px rgba(120, 40, 160, 0.3), 0 18px 50px -30px rgba(11, 10, 13, 0.16);
25	
26	  --brand-gradient: linear-gradient(100deg, #f72570 0%, #ff6b67 44%, #ff9868 66%, #a33dff 100%);
27	}
28	
29	/* ══════════════════════════════════════════════════════════════════════════
30	   KODELY PRODUCT SURFACE
31	   ══════════════════════════════════════════════════════════════════════════
32	   The tokens above (--accent, --brand-gradient, --glow…) are the MARKETING
33	   system and are ported from the approved reference mockup. Do not repoint
34	   them; the marketing pages read them directly.
35	
36	   These are the PRODUCT tokens — the portal and the builder. They are additive
37	   and share the same brand hues on purpose, because a customer crosses
38	   marketing → portal → builder in one session and the seam should be
39	   invisible. What differs is density: marketing is a poster, the product is an
40	   instrument, so the product gets a surface ramp, semantic status colour, and
41	   a tighter spacing/type scale that the marketing pages have no use for.
42	
43	   TYPEFACE: deliberately still Geist. A display serif was considered and
44	   rejected — the marketing site the customer just came from is set in Geist,
45	   and swapping faces at the /dashboard boundary would break the one continuity
46	   requirement that matters most. "Premium" here is bought with the type SCALE,
47	   tracking, tabular numerals and weight discipline below, not a second family.
48	
49	   NEUTRALS are hue-biased toward the brand (a touch of magenta in light, a
50	   touch of indigo in dark) rather than pure grey, so panels sit in the same
51	   world as the accent instead of looking like a default admin theme. */
52	:root {
53	  /* Surface ramp — canvas sits BEHIND panels, so it is darker than --surface
54	     in light mode. Everything else steps up from there. */
55	  --surface-canvas: #faf8fb;
56	  --surface: #ffffff;
57	  --surface-2: #f5f2f7;
58	  --surface-3: #ece8f0;
59	  --surface-inset: #f8f6fa;
60	
61	  --border-soft: rgba(11, 10, 13, 0.06);
62	  --border-mid: rgba(11, 10, 13, 0.1);
63	  --border-strong: rgba(11, 10, 13, 0.18);
64	
65	  --text-1: #16131c;
66	  --text-2: #605b6b;
67	  --text-3: #948da3;
68	  --text-inv: #ffffff;
69	
70	  /* Brand, as flat UI colour. --accent is the marketing pink; these add the
71	     tints a product needs (a fill you can put text on, a focus ring). */
72	  --brand: #e01b6e;
73	  --brand-hover: #c4155e;
74	  --brand-tint: rgba(224, 27, 110, 0.08);
75	  --brand-tint-2: rgba(224, 27, 110, 0.14);
76	  --brand-ring: rgba(224, 27, 110, 0.38);
77	  --brand-ink: #a41050;
78	  /* A second brand hue purely for chart gradients (bar fills, donut
79	     segments) — pairs with --brand so a gradient has somewhere to go
80	     without reaching for the marketing --brand-gradient, which stays
81	     reserved for the primary CTA / credits cards. */
82	  --brand-chart-2: #a33dff;
83	  --brand-chart-3: #ff9868;
84	
85	  /* Semantic status. Kept clearly OFF the brand ramp: a "success" that reads
86	     as brand pink is unreadable as status, and the peach in the gradient is
87	     close enough to amber that warning is pushed yellow-ward to separate. */
88	  --ok: #0d8f5b;
89	  --ok-tint: rgba(13, 143, 91, 0.1);
90	  --warn: #a86a08;
91	  --warn-tint: rgba(214, 145, 20, 0.14);
92	  --danger: #cf2b3c;
93	  --danger-tint: rgba(207, 43, 60, 0.1);
94	  --info: #5b4ee0;
95	  --info-tint: rgba(91, 78, 224, 0.1);
96	
97	  /* Elevation. Two axes deliberately: a neutral drop for depth plus a faint
98	     violet cast, which is what stops white cards on a white-ish canvas from
99	     looking like flat rectangles with a border. */
100	  --e1: 0 1px 2px rgba(11, 10, 13, 0.04);
101	  --e2:
102	    0 1px 2px rgba(11, 10, 13, 0.04), 0 8px 20px -12px rgba(90, 40, 140, 0.18);
103	  --e3:
104	    0 2px 4px rgba(11, 10, 13, 0.05), 0 24px 48px -24px rgba(90, 40, 140, 0.26);
105	
106	  /* Radii. "Rounded but not bubbly" — the step from control (10) to card (14)
107	     to sheet (20) is what reads as considered; one radius everywhere is what
108	     reads as a Tailwind default. */
109	  --r-xs: 6px;
110	  --r-sm: 8px;
111	  --r-md: 10px;
112	  --r-lg: 14px;
113	  --r-xl: 20px;
114	  --r-2xl: 28px;
115	  --r-full: 999px;
116	
117	  /* Motion. One easing for everything that enters or resizes, one for state
118	     flips. Durations are short on purpose: "fast and expensive", not flashy. */
119	  --ease: cubic-bezier(0.16, 1, 0.3, 1);
120	  --ease-io: cubic-bezier(0.4, 0, 0.2, 1);
121	  --t-1: 120ms;
122	  --t-2: 200ms;
123	  --t-3: 380ms;
124	
125	  --sidebar-w: 248px;
126	  --sidebar-w-collapsed: 68px;
127	  --topbar-h: 60px;
128	}
