213	/* Exposed to Tailwind so the product can be written as `bg-surface`,
214	   `text-text-2`, `border-border-mid`, `rounded-lg` etc. rather than as
215	   arbitrary-value brackets on every element. This is the whole reason the
216	   design system holds together across pages written by different hands. */
217	@theme inline {
218	  --color-background: var(--background);
219	  --color-foreground: var(--foreground);
220	  --font-sans: var(--font-geist-sans);
221	  --font-mono: var(--font-geist-mono);
222	
223	  --color-canvas: var(--surface-canvas);
224	  --color-surface: var(--surface);
225	  --color-surface-2: var(--surface-2);
226	  --color-surface-3: var(--surface-3);
227	  --color-inset: var(--surface-inset);
228	
229	  --color-hair: var(--border-soft);
230	  --color-line-mid: var(--border-mid);
231	  --color-line-strong: var(--border-strong);
232	
233	  --color-ink: var(--text-1);
234	  --color-ink-2: var(--text-2);
235	  --color-ink-3: var(--text-3);
236	  --color-ink-inv: var(--text-inv);
237	
238	  --color-brand: var(--brand);
239	  --color-brand-hover: var(--brand-hover);
240	  --color-brand-tint: var(--brand-tint);
241	  --color-brand-tint-2: var(--brand-tint-2);
242	  --color-brand-ink: var(--brand-ink);
243	
244	  --color-ok: var(--ok);
245	  --color-ok-tint: var(--ok-tint);
246	  --color-warn: var(--warn);
247	  --color-warn-tint: var(--warn-tint);
248	  --color-danger: var(--danger);
249	  --color-danger-tint: var(--danger-tint);
250	  --color-info: var(--info);
251	  --color-info-tint: var(--info-tint);
252	
253	  --radius-xs: var(--r-xs);
254	  --radius-sm: var(--r-sm);
255	  --radius-md: var(--r-md);
256	  --radius-lg: var(--r-lg);
257	  --radius-xl: var(--r-xl);
258	  --radius-2xl: var(--r-2xl);
259	
260	  --shadow-e1: var(--e1);
261	  --shadow-e2: var(--e2);
262	  --shadow-e3: var(--e3);
263	}
