312	/* Ambient background — one very slow, very soft light behind every
313	   marketing page. Fixed, never scrolls, never shifts color — the motion
314	   budget is spent on foreground elements, not this. */
315	.aura {
316	  position: fixed;
317	  inset: 0;
318	  z-index: 0;
319	  pointer-events: none;
320	  overflow: hidden;
321	}
322	.aura b {
323	  position: absolute;
324	  border-radius: 50%;
325	  filter: blur(120px);
326	  opacity: 0.6;
327	}
328	.aura .a1 {
329	  width: 52vw;
330	  height: 52vw;
331	  left: -8vw;
332	  top: -14vw;
333	  background: radial-gradient(closest-side, var(--glow), transparent);
334	}
335	.aura .a2 {
336	  width: 46vw;
337	  height: 46vw;
338	  right: -10vw;
339	  bottom: -4vw;
340	  background: radial-gradient(closest-side, var(--glow-2), transparent);
341	}
