343	/* The prompt-box glow ring (PromptHero) — a Gemini-style "chasing light"
344	   ring, rebuilt using only decade-old, maximally-compatible CSS: plain
345	   `transform: rotate()` and `overflow: hidden` clipping. No @property, no
346	   CSS masking — both were dropped after repeated reports that the effect
347	   still wasn't appearing correctly even in a fresh browser with a verified
348	   non-cached, up-to-date stylesheet, which means the earlier @property +
349	   mask-composite combination (both comparatively modern CSS features) was
350	   the most likely remaining suspect, even though I could not get direct
351	   visual confirmation either way in this environment.
352	
353	   The technique: each layer is a STATIC outer clipper
354	   (`.glow-clip-a/-b`, position:absolute, overflow:hidden, never
355	   transforms) containing one OVERSIZED inner rotator
356	   (`.glow-spin-a/-b`, ~2x the clipper's size, centered via inset:-50%).
357	   Only the inner rotator spins via plain `transform: rotate()` — since
358	   it's oversized, its corners sweeping outside a same-sized box (the
359	   original "wide rectangle rotated as a rigid body" bug) never matters:
360	   they're clipped away by the static outer box at every angle. The
361	   composer sitting on top (z-10, opaque) covers the rotator's entire
362	   interior, leaving only the outer few px visible as a ring — no masking
363	   needed for that either. */
364	@keyframes glow-spin {
365	  to {
366	    transform: rotate(360deg);
367	  }
368	}
369	.glow-spin-a {
370	  animation: glow-spin 9s linear infinite;
371	}
372	.glow-spin-b {
373	  animation: glow-spin 14s linear infinite reverse;
374	}
375	
376	/* Entrance fade-in — plain CSS on the static outer clipper, not a
377	   framer-motion `whileInView` (depends on IntersectionObserver + React
378	   state + framer's scheduling — more moving parts than necessary here).
379	   `forwards` is load-bearing: without it, the element snaps back to its
380	   non-animated base style the instant the single iteration ends. */
381	@keyframes glow-fade-in-a {
382	  from {
383	    opacity: 0;
384	    transform: scale(0.94);
385	  }
386	  to {
387	    opacity: 0.35;
388	    transform: scale(1);
389	  }
390	}
391	@keyframes glow-fade-in-b {
392	  from {
393	    opacity: 0;
394	    transform: scale(0.94);
395	  }
396	  to {
397	    opacity: 0.2;
398	    transform: scale(1);
399	  }
400	}
401	
402	/* Ambient pulse — a slow breathe, kept subtle so it reads as the glow
403	   "living" rather than blinking. Runs as a THIRD animation chained after
404	   the entrance: the fade-in owns opacity for its first 0.8s, then this
405	   takes over from the same value it settled on (0.35 / 0.2), so there is
406	   no jump at the handoff — keep the two in sync when retuning intensity.
407	   Its delay must match the fade-in's duration.
408	   The floor never approaches 0 — the glow dims and brightens, it never
409	   disappears. */
410	@keyframes glow-pulse-a {
411	  0%,
412	  100% {
413	    opacity: 0.35;
414	  }
415	  50% {
416	    opacity: 0.5;
417	  }
418	}
419	@keyframes glow-pulse-b {
420	  0%,
421	  100% {
422	    opacity: 0.2;
423	  }
424	  50% {
425	    opacity: 0.33;
426	  }
427	}
428	.glow-clip-a {
429	  animation:
430	    glow-fade-in-a 0.8s cubic-bezier(0.16, 1, 0.3, 1) both,
431	    glow-pulse-a 4.5s ease-in-out 0.8s infinite;
432	}
433	.glow-clip-b {
434	  animation:
435	    glow-fade-in-b 0.9s cubic-bezier(0.16, 1, 0.3, 1) 0.1s both,
436	    glow-pulse-b 6s ease-in-out 1s infinite;
437	}
