439	/* Scroll entrance for the hero mock (HeroMock.tsx). A CSS transition
440	   toggled by an `is-entered` class from an IntersectionObserver — no
441	   dependence on framer-motion's in-view scheduling, which applied its
442	   initial styles here but never actually triggered. */
443	@keyframes hero-mock-in {
444	  from {
445	    opacity: 0;
446	    transform: translateY(56px) scale(0.94);
447	  }
448	  to {
449	    opacity: 1;
450	    transform: translateY(0) scale(1);
451	  }
452	}
