454	/* Fallback for browsers without scroll-driven animation support: play the
455	   entrance once on load. Not as nice as scroll-linked, but never leaves
456	   the mock stuck invisible. */
457	.hero-mock-enter {
458	  animation: hero-mock-in 0.9s cubic-bezier(0.16, 1, 0.3, 1) both;
459	}
460	
461	/* The real thing: a native scroll-driven animation, progressed by the
462	   element's own position in the viewport. No IntersectionObserver, no
463	   scroll listener, no React state — every JS-based trigger tried here
464	   (framer's whileInView, a raw IntersectionObserver, a scroll listener)
465	   failed to fire in practice, and this removes that entire class of
466	   failure. `view()` ties progress to the element crossing the viewport;
467	   the range runs from just after it appears to a third of the way up, so
468	   it finishes as you arrive at it rather than while it's still an
469	   off-screen sliver. */
470	@supports (animation-timeline: view()) {
471	  .hero-mock-enter {
472	    /* Longhands, not the `animation` shorthand: the shorthand defaults
473	       animation-duration to 0s when it's omitted, which — combined with
474	       fill:both — snapped straight to the end state at every scroll
475	       position (i.e. no visible animation at all). Scroll-driven
476	       animations need `auto`, which maps progress onto animation-range.
477	       The shorthand also resets animation-timeline, so setting these
478	       individually keeps the two declarations from fighting. */
479	    animation-name: hero-mock-in;
480	    animation-duration: auto;
481	    animation-timing-function: linear;
482	    animation-fill-mode: both;
483	    animation-timeline: view();
484	    /* Spans the element's whole entry into the viewport: starts just after
485	       its top edge appears and finishes exactly when it's fully on screen.
486	       Both endpoints in the same phase keeps it predictable (an earlier
487	       `entry 15% cover 38%` mixed phases, which is legal but harder to
488	       reason about and compressed the motion into a shorter scroll). */
489	    animation-range: entry 10% entry 100%;
490	  }
491	}
