690	/* One focus treatment for the whole product. Always visible, never removed —
691	   a ring that only shows on :focus-visible still has to exist.
692	
693	   Never pair either of these with `outline-none`. Three separate second focus
694	   systems had already appeared (the form primitives, the segmented control and
695	   the onboarding panel), two of which cancelled the outline entirely. If a
696	   control needs an EXTRA cue — a border colour change on an input, say — add it
697	   alongside these, never instead of them. */
698	.k-focus:focus-visible {
699	  outline: 2px solid var(--brand-ring);
700	  outline-offset: 2px;
701	}
702	
703	/* The same ring for a control whose real input is visually hidden: a <label>
704	   wrapping an sr-only radio or checkbox never matches :focus-visible itself,
705	   because the input is what receives focus. Same values, so the product still
706	   has exactly one focus appearance — this is a second SELECTOR, not a second
707	   system. */
708	.k-focus-within:has(:focus-visible) {
709	  outline: 2px solid var(--brand-ring);
710	  outline-offset: 2px;
711	}
712	
713	/* Type scale. Display sizes get negative tracking (optical correction — at
714	   32px+ the default spacing reads loose); the label size gets positive
715	   tracking and uppercase, which is the only place caps are used. */
716	.k-display {
717	  font-size: clamp(1.75rem, 1.2rem + 1.6vw, 2.35rem);
718	  line-height: 1.1;
719	  letter-spacing: -0.028em;
