901	    transition-duration: 0.2s !important;
902	  }
903	  /* Blur is motion-adjacent for some vestibular users and, unlike the
904	     animations above, is not covered by the duration override. */
905	  .k-preview-busy {
906	    filter: saturate(0.82);
907	    transform: none;
908	  }
