41	// The rotating gradient inside each glow clip MUST be a square that is
42	// larger than the clip's diagonal, or it stops covering the clip partway
43	// through its own rotation and the ring visibly vanishes and returns on a
44	// loop. (An `inset-[-50%]` made it 2x the clip in BOTH axes — e.g.
45	// 1372x296 for a wide composer. Rotated 90deg that occupies 296x1372: only
46	// 296px wide, far short of the ~686px the clip needs covered. Hence "the
47	// glow keeps disappearing.")
48	//
49	// 200% width + aspectRatio 1 gives a square of side 2*clipWidth, which
50	// always exceeds the diagonal. Centering uses margins rather than a
51	// translate because `transform` is owned by the rotation keyframes and a
52	// transform in the animation would override any translate set here —
53	// percentage margins (all sides, per spec) resolve against the containing
54	// block's WIDTH, so -100% on both axes lands the square's center exactly
55	// on the clip's center.
56	const SPIN_SQUARE: React.CSSProperties = {
57	  position: "absolute",
58	  left: "50%",
59	  top: "50%",
60	  width: "200%",
61	  aspectRatio: "1",
62	  marginLeft: "-100%",
63	  marginTop: "-100%",
64	};
