66	// The Web Speech API has no types in TypeScript's DOM lib, so this is a
67	// minimal hand-written shim covering exactly the surface used below —
68	// narrower than the real spec on purpose, so it can't quietly drift into
69	// asserting support for members this component never touches.
70	type SpeechRecognitionAlternativeLike = { readonly transcript: string };
71	type SpeechRecognitionResultLike = {
72	  readonly length: number;
73	  readonly [index: number]: SpeechRecognitionAlternativeLike;
74	};
75	type SpeechRecognitionEventLike = {
76	  readonly results: {
77	    readonly length: number;
78	    readonly [index: number]: SpeechRecognitionResultLike;
79	  };
