93	// Narrowed locally rather than via `declare global`: augmenting Window would
94	// collide with the (differently-shaped) definitions any future TS DOM lib
95	// ships for this API.
96	type SpeechCapableWindow = {
97	  SpeechRecognition?: SpeechRecognitionCtor;
98	  webkitSpeechRecognition?: SpeechRecognitionCtor;
99	};
