103	  const w = window as unknown as SpeechCapableWindow;
104	  return w.SpeechRecognition ?? w.webkitSpeechRecognition ?? null;
105	}
106	
107	// Feature detection is *external* state: it is unknowable while rendering on
108	// the server, and rendering the mic button in the server HTML would be a
