116	
117	export function PromptBox({
118	  value,
119	  onChange,
120	  onSubmit,
121	  canSubmit,
122	  onAttachFile,
123	  children,
124	}: {
125	  value: string;
126	  onChange: (next: string) => void;
127	  onSubmit: () => void;
128	  /** False while the box is empty, or while a build would be refused outright. */
129	  canSubmit: boolean;
130	  /**
131	   * A file arrived via the "+" picker, a paste, or a drop onto the box.
132	   * `extraIgnored` is the count of additional files dropped alongside it that
133	   * were never looked at — the pipeline only ever attaches one, so the
134	   * caller can tell the customer the rest were ignored rather than silently
135	   * dropping them with no explanation. PromptBox does no validation of its
