163	    if (listening) {
164	      recognitionRef.current?.stop();
165	      return;
166	    }
167	
168	    const rec = new Ctor();
169	    rec.continuous = true;
170	    rec.interimResults = true;
171	    rec.lang = "en-US";
172	    baseValueRef.current = value ? value.trim() + " " : "";
