204	    e.preventDefault();
205	  }
206	  function handleDragLeave(e: React.DragEvent) {
207	    e.preventDefault();
208	    dragDepth.current = Math.max(0, dragDepth.current - 1);
209	    if (dragDepth.current === 0) setDragOver(false);
210	  }
211	  function handleDrop(e: React.DragEvent) {
212	    e.preventDefault();
213	    dragDepth.current = 0;
214	    setDragOver(false);
215	    const files = Array.from(e.dataTransfer.files);
216	    if (files.length > 0) onAttachFile(files[0], files.length - 1);
