219	  function handlePaste(e: React.ClipboardEvent<HTMLTextAreaElement>) {
220	    const item = Array.from(e.clipboardData.items).find(
221	      (it) => it.kind === "file" && it.type.startsWith("image/"),
222	    );
223	    if (!item) return; // no image on the clipboard — let normal text paste happen
224	    const file = item.getAsFile();
225	    if (!file) return;
226	    // Stops the browser from ALSO inserting a filename or a broken inline
227	    // image placeholder into the textarea alongside the real attachment.
228	    e.preventDefault();
229	    onAttachFile(file);
230	  }
231	
232	  function handlePicked(e: React.ChangeEvent<HTMLInputElement>) {
233	    const file = e.target.files?.[0];
234	    // Cleared unconditionally so picking the SAME file twice in a row still
235	    // fires this handler the second time — the browser only emits `change`
236	    // on a value transition, and an unchanged `value` would silently no-op.
237	    e.target.value = "";
238	    if (file) onAttachFile(file);
239	  }
240	
241	  return (
242	    // This wrapper is sized to exactly the composer box — the glow layers
243	    // below position with -inset-N relative to IT, so the glow hugs just the
244	    // box and never the heading or the chips around it.
245	    <div className="relative">
246	      {/* The glow — a Gemini-style "chasing light" ring, built with only plain
247	          `transform: rotate()` + `overflow: hidden` clipping: no @property, no
248	          CSS masking (both dropped after they didn't visibly work even in a
249	          fresh, verified non-cached browser). Two layers: a thin bright one
250	          and a soft blurred halo.
251	
252	          The blur lives on the CLIP element, not on the rotating child. That
253	          ordering matters: filters apply AFTER the element (and its
254	          overflow:hidden clipping) is rendered, so the blur softens the clip's
255	          hard outer cutoff and lets the light bleed beyond the clip's bounds —
256	          a real falloff. With the blur on the child instead, the clip's crisp
257	          edge survives and the result reads as a chunky solid border.
258	
259	          Opacity is fixed, not keyed off `focused` — an earlier version dimmed
260	          on blur, which read as "disappearing". The composer's own border
261	          below is the right place for a focus affordance; this ring stays
262	          constant. The entrance fade and the ambient pulse are the
263	          glow-fade-in and glow-pulse keyframes on the outer clipper, so the
264	          global prefers-reduced-motion rule in globals.css already covers
265	          them — nothing here animates outside CSS.
266	
267	          NO NEGATIVE Z-INDEX HERE. `-z-10` drops these layers behind the
268	          nearest opaque background and they are then invisible forever. The
269	          layers sit at the default level and the composer is lifted above them
270	          with z-10, which needs no stacking-context trickery to hold. */}
271	      <div
272	        aria-hidden
273	        className="glow-clip-a pointer-events-none absolute -inset-[3px] overflow-hidden rounded-[1.9rem] blur-[5px]"
274	      >
275	        <div
276	          className="glow-spin-a"
277	          style={{
278	            ...SPIN_SQUARE,
279	            // Stops are pushed into distinct quadrants so the colour visibly
280	            // travels around the box as this rotates — closely-spaced hues
281	            // just blur into one flat pink.
282	            background:
283	              "conic-gradient(#f72570 0deg, #a33dff 90deg, #ff9868 180deg, #ff6b67 270deg, #f72570 360deg)",
284	          }}
285	        />
286	      </div>
287	      <div
288	        aria-hidden
289	        className="glow-clip-b pointer-events-none absolute -inset-[14px] overflow-hidden rounded-[2.4rem] blur-[22px]"
290	      >
291	        <div
292	          className="glow-spin-b"
293	          style={{
294	            ...SPIN_SQUARE,
295	            background:
296	              "conic-gradient(from 180deg, #a33dff 0deg, #f72570 90deg, #ff9868 180deg, #ff6b67 270deg, #a33dff 360deg)",
297	          }}
298	        />
299	      </div>
300	
301	      {/* The glass composer. Opaque enough that the animated ring behind it
302	          reads as a halo around the box, not a wash bleeding through onto the
303	          text — earlier versions were translucent enough that the strong glow
304	          showed straight through onto the placeholder. Still picks up a faint
305	          frosted quality from backdrop-blur, just not at the cost of
306	          legibility. */}
