1	"use client";
2	
3	import { useCallback, useEffect, useRef, useState } from "react";
4	import { useRouter } from "next/navigation";
5	import { Composer, type AssistResult, type AttachedLogo, type CreditContext } from "./Composer";
6	import { BuildLaunch } from "./BuildLaunch";
7	import {
8	  INITIAL_BUILD,
9	  parseStreamEvent,
10	  reduceBuild,
11	  type BuildProgress,
12	  type BuildSignal,
13	} from "./build-steps";
14	
15	/** Same shape the homepage hand-off uses (lib/pending-prompt.ts) so a project
16	    started here is named the way a project started there is. Reimplemented
17	    rather than imported because that helper is not exported. */
18	function deriveName(prompt: string): string {
19	  const trimmed = prompt.trim().replace(/\s+/g, " ");
20	  return trimmed.length > 60 ? trimmed.slice(0, 57) + "…" : trimmed || "New site";
21	}
22	
23	type Phase = "compose" | "building";
24	
25	/**
26	 * WHAT HAPPENS TO A LOGO AND A PALETTE HANDED OVER BY A HELPER FLOW
27	 *
28	 * Both TemplatePickerModal and InlineWizard can return `logoDataUrl` and
29	 * `palette`. Neither may be accepted from the customer and then dropped, so:
30	 *
31	 * PALETTE reaches the build as TEXT. Both flows already write their chosen
32	 * hexes into the prompt they assemble (see the `- Palette: <id> (#a to #b)`
33	 * line in lib/wizard.ts and components/templates/intake.ts), and Composer's
34	 * withPalette() appends them to the composer's own text in the case where they
35	 * are somehow absent. So the colours are in the box, where the customer can
36	 * read and change them, and they travel in the request like any other words.
37	 *
38	 * LOGO reaches the build as the `image` field on POST /api/generate — the
39	 * same field the reference-image control used to fill, and the reason the
40	 * plumbing for it survives that control's removal. components/templates/logo.ts
41	 * and components/wizard/inline-logo.ts both emit `data:image/png;base64,…`
42	 * precisely because that is the one thing the route's regex accepts, and the
43	 * route hands it to the model on ATTEMPT 1 only. The composer says exactly that
44	 * beside the thumbnail rather than implying it is uploaded and stored.
45	 *
46	 * NOT the brand-kit route (PUT /api/projects/[id]/brand), which would compile
47	 * the logo into src/components/brand/BrandLogo.tsx and seed the palette as a
48	 * Tailwind @theme block — a stronger path. buildBrandKit() in lib/brand-kit.ts
49	 * REQUIRES a business name and refuses without one, and neither pinned result
50	 * type carries one; deriving a business name from the first 60 characters of a
51	 * brief would put "A one-page site for my barbershop with services" into the
52	 * customer's header, footer and <title> verbatim, which is the exact sentence
53	 * brandPromptFragment() promises to use unaltered. A brand kit is the right
54	 * home for these once there is a name to give it, and the prompts both flows
55	 * write already tell the model honestly that the logo is guidance rather than
56	 * an asset it can embed.
57	 */
58	export function CreateFlow({
59	  initialPrompt,
60	  templateName,
61	  credits,
62	  canTopUp,
63	}: {
64	  initialPrompt: string;
65	  templateName: string | null;
66	  credits: CreditContext;
67	  canTopUp: boolean;
68	}) {
69	  const router = useRouter();
70	  const [phase, setPhase] = useState<Phase>("compose");
71	  const [prompt, setPrompt] = useState(initialPrompt);
72	  const [startedFrom, setStartedFrom] = useState<string | null>(templateName);
73	  const [logo, setLogo] = useState<AttachedLogo | null>(null);
74	  const [submitted, setSubmitted] = useState("");
75	  const [progress, setProgress] = useState<BuildProgress>(INITIAL_BUILD);
76	  const [projectId, setProjectId] = useState<string | null>(null);
77	  const [stopping, setStopping] = useState(false);
78	  /** True only when the server REFUSED the request with a non-2xx response.
79	      Those paths (kill switch, no credits, spend cap, rate limit) all return
80	      before app/api/generate/route.ts writes a Build row or a user Message, so
81	      the project is still pristine and a retry is genuinely a first build. */
82	  const [retrySafe, setRetrySafe] = useState(false);
83	
84	  const abortRef = useRef<AbortController | null>(null);
85	  const stoppedRef = useRef(false);
86	  /** Mirrors `progress` for the async loop, which cannot read state. */
87	  const stateRef = useRef<BuildProgress>(INITIAL_BUILD);
88	
89	  const running = phase === "building" && progress.outcome === "running";
90	
91	  // Closing or reloading the tab drops the response body, which aborts the
92	  // model request server-side. Warning about it is the honest thing to do —
93	  // the alternative is someone losing a build they were watching.
94	  useEffect(() => {
95	    if (!running) return;
96	    const warn = (e: BeforeUnloadEvent) => e.preventDefault();
97	    window.addEventListener("beforeunload", warn);
98	    return () => window.removeEventListener("beforeunload", warn);
99	  }, [running]);
100	
101	  // Navigating away inside the app (a sidebar link, the back button) unmounts
102	  // this component but does NOT cancel an in-flight fetch — the build would
103	  // keep running for a screen nobody is looking at and then yank the customer
104	  // into the builder from wherever they had gone. Aborting on unmount is what
105	  // makes "leaving stops the build" a true statement rather than a hope, and
106	  // an aborted build is written FAILED with creditsCharged: 0.
107	  //
108	  // Safe on the success path: `run` clears abortRef in its finally block
109	  // before React processes the navigation router.push() schedules.
110	  useEffect(() => () => abortRef.current?.abort(), []);
111	
112	  const signal = useCallback((s: BuildSignal) => {
113	    const next = reduceBuild(stateRef.current, s);
114	    stateRef.current = next;
115	    setProgress(next);
116	    return next;
117	  }, []);
118	
119	  const run = useCallback(
120	    async (text: string, imageDataUrl: string | null, existingProjectId: string | null) => {
121	      stateRef.current = INITIAL_BUILD;
122	      setProgress(INITIAL_BUILD);
123	      setStopping(false);
124	      setRetrySafe(false);
125	      stoppedRef.current = false;
126	      setSubmitted(text);
127	      setPhase("building");
128	
129	      let id = existingProjectId;
130	
131	      // ── 1. The project ───────────────────────────────────────────────────
132	      if (id === null) {
133	        try {
134	          const res = await fetch("/api/projects", {
135	            method: "POST",
136	            headers: { "Content-Type": "application/json" },
137	            body: JSON.stringify({ name: deriveName(text) }),
138	          });
139	          const body: unknown = await res.json().catch(() => null);
140	          const created =
141	            typeof body === "object" && body !== null
142	              ? (body as { project?: { id?: unknown } }).project
143	              : undefined;
144	          if (!res.ok || typeof created?.id !== "string") {
145	            const message =
146	              typeof body === "object" && body !== null && typeof (body as { error?: unknown }).error === "string"
147	                ? (body as { error: string }).error
148	                : "Your project couldn't be created. Nothing was charged — try again.";
149	            signal({ kind: "failed", message });
150	            setRetrySafe(true);
151	            return;
152	          }
153	          id = created.id;
154	        } catch {
155	          signal({
156	            kind: "failed",
157	            message:
158	              "Your project couldn't be created — the request didn't reach Kodely. Nothing was charged.",
159	          });
160	          setRetrySafe(true);
161	          return;
162	        }
163	        setProjectId(id);
164	      }
165	      signal({ kind: "project-created" });
166	
167	      // ── 2. The build ─────────────────────────────────────────────────────
168	      const controller = new AbortController();
169	      abortRef.current = controller;
170	
171	      try {
172	        const res = await fetch("/api/generate", {
173	          method: "POST",
174	          headers: { "Content-Type": "application/json" },
175	          body: JSON.stringify({ projectId: id, prompt: text, image: imageDataUrl }),
176	          signal: controller.signal,
177	        });
178	
179	        if (!res.ok || !res.body) {
180	          const body: unknown = await res.json().catch(() => null);
181	          const message =
182	            typeof body === "object" && body !== null && typeof (body as { error?: unknown }).error === "string"
183	              ? (body as { error: string }).error
184	              : "The build couldn't be started.";
185	          // A refusal happens before anything is written or charged, so this
186	          // project is still a clean slate.
187	          setRetrySafe(true);
188	          signal({ kind: "failed", message });
189	          return;
190	        }
191	
192	        signal({ kind: "accepted" });
193	
194	        const reader = res.body.getReader();
195	        const decoder = new TextDecoder();
196	        let buffer = "";
197	        let sawTerminal = false;
198	
199	        for (;;) {
200	          const { done, value } = await reader.read();
201	          if (done) break;
202	          buffer += decoder.decode(value, { stream: true });
203	
204	          const frames = buffer.split("\n\n");
205	          buffer = frames.pop() ?? "";
206	
207	          for (const frame of frames) {
208	            if (!frame.startsWith("data: ")) continue;
209	            let raw: unknown;
210	            try {
211	              raw = JSON.parse(frame.slice(6));
212	            } catch {
213	              continue;
214	            }
215	            const event = parseStreamEvent(raw);
216	            if (event === null) continue;
217	            if (event.type === "done" || event.type === "error") sawTerminal = true;
218	            signal({ kind: "sse", event });
219	          }
220	        }
221	
222	        // The route always sends `done` or `error` unless the client went
223	        // away. A stream that ends without either IS a dropped connection —
224	        // saying "finished" here would be the exact lie this screen exists to
225	        // avoid.
226	        if (!sawTerminal) signal({ kind: "lost" });
227	
228	        if (stateRef.current.outcome === "succeeded" && id !== null) {
229	          router.push(`/projects/${id}`);
230	        }
231	      } catch {
232	        if (stoppedRef.current) signal({ kind: "stopped" });
233	        else
234	          signal({
235	            kind: "failed",
236	            message:
237	              "The connection to the build dropped. Nothing was charged — open the project to see what was written.",
238	          });
239	      } finally {
240	        abortRef.current = null;
241	        setStopping(false);
242	      }
243	    },
244	    [router, signal],
245	  );
246	
247	  function stop() {
248	    if (!running || stopping || abortRef.current === null) return;
249	    stoppedRef.current = true;
250	    setStopping(true);
251	    // A real cancel: aborting the fetch closes the response body, which fires
252	    // cancel() on the route's stream and aborts the model request. The Build
253	    // row is written FAILED with creditsCharged: 0.
254	    abortRef.current.abort();
255	  }
256	
257	  if (phase === "building") {
258	    return (
259	      <BuildLaunch
260	        progress={progress}
261	        prompt={submitted}
262	        projectId={projectId}
263	        stopping={stopping}
264	        onStop={stop}
265	        onRetry={
266	          retrySafe && progress.outcome === "failed"
267	            ? () => void run(submitted, logo?.dataUrl ?? null, projectId)
268	            : null
269	        }
270	        onEdit={() => {
271	          setPhase("compose");
272	          setProgress(INITIAL_BUILD);
273	          stateRef.current = INITIAL_BUILD;
274	        }}
275	      />
276	    );
277	  }
278	
279	  return (
280	    // Centered in the visible content area, not just at the top of a tall
281	    // scroll container — the min-height subtracts the shell's own topbar and
282	    // padding so "centered" means centered in what's actually on screen,
283	    // approximately, across the range of real viewport heights rather than
284	    // exactly on any one of them.
285	    <div className="flex min-h-[calc(100dvh-var(--topbar-h)-7rem)] items-center justify-center lg:min-h-[calc(100dvh-var(--topbar-h)-9rem)]">
286	    <Composer
287	      value={prompt}
288	      onChange={setPrompt}
289	      logo={logo}
290	      onLogoChange={setLogo}
291	      // A helper flow replaces the box's contents wholesale rather than
292	      // appending: the customer picked a template or answered the wizard
293	      // specifically to REPLACE whatever placeholder text was there, and
294	      // appending would leave both texts arguing with each other in the
295	      // request. The prompt still lands in the editable box, not the request,
296	      // so nothing is submitted without the customer having seen it.
297	      onAssist={(result: AssistResult) => {
298	        setPrompt(result.prompt);
299	        setLogo(result.logo);
300	        setStartedFrom(result.templateName);
301	      }}
302	      onSubmit={() => void run(prompt.trim(), logo?.dataUrl ?? null, projectId)}
303	      fromTemplate={startedFrom}
304	      credits={credits}
305	      canTopUp={canTopUp}
306	    />
307	    </div>
308	  );
309	}
