1	import { cookies } from "next/headers";
2	import { redirect } from "next/navigation";
3	import type { Metadata } from "next";
4	import type { ReactNode } from "react";
5	import { getCurrentUser } from "@/lib/auth";
6	import { averageBuildCredits, getBalance } from "@/lib/credits";
7	import { billingEnabled } from "@/lib/stripe";
8	import { AppShell } from "@/components/app/AppShell";
9	
10	// Every page in the group reads the session, so none of it can ever be
11	// statically rendered. Being explicit keeps that intentional rather than
12	// incidental.
13	export const dynamic = "force-dynamic";
14	
15	/* ONE title convention for the whole portal. Before this, two pages set
16	   "X — Kodely" by hand, two set a bare "X", and the remaining seven set no
17	   metadata at all — so /dashboard/billing rendered the MARKETING homepage's
18	   "Kodely — AI Website Builder" in the browser tab. Putting the template on
19	   the group layout means a page declares only its own noun and cannot get the
20	   suffix wrong. Next requires `default` whenever `template` is set; it is what
21	   a portal page with no title of its own falls back to. */
22	export const metadata: Metadata = {
23	  title: { default: "Kodely", template: "%s — Kodely" },
24	};
25	
26	/* The signed-in product shell: /dashboard/*, /settings, /support.
27	   Deliberately NOT wrapping /templates, /wizard, /pricing or /blog — those are
28	   public marketing pages with their own nav, and a signed-out visitor must
29	   still be able to read them. The portal has its own in-shell copies of the
30	   template gallery and the prompt entry for signed-in customers.
31	
32	   The builder (/projects/[id]) is also outside this group on purpose: it is
33	   full-bleed chat + preview and a 248px rail would take a fifth of the
34	   customer's site preview to show navigation they are not using while
35	   building. It carries its own back-to-dashboard affordance instead.
36	
37	   AUTH: this redirect is the primary gate, but every page below ALSO resolves
38	   the user itself. A layout does not re-render on every navigation within its
39	   own segment, and route handlers never sit under it at all — the same reason
40	   app/admin/layout.tsx says so in its own comment. */
41	export default async function PortalLayout({ children }: { children: ReactNode }) {
42	  const user = await getCurrentUser();
43	  if (!user) redirect("/login");
44	
45	  // Three cheap reads, all needed by the rail's credits card, which is on
46	  // every screen. averageBuildCredits() falls back to a global constant for
47	  // someone with no history, which is fine here — the card only uses it to
48	  // phrase the balance as "about N builds", never to claim it is *your*
49	  // average. Pages that make that stronger claim gate it on a build count.
50	  const [balance, avgBuildCredits, jar] = await Promise.all([
51	    getBalance(user.id),
52	    averageBuildCredits(user.id),
53	    cookies(),
54	  ]);
55	
56	  return (
57	    <AppShell
58	      initialCollapsed={jar.get("kodely-sidebar")?.value === "1"}
59	      user={{ email: user.email, name: user.name }}
60	      balance={balance}
61	      avgBuildCredits={avgBuildCredits}
62	      canTopUp={billingEnabled()}
63	    >
64	      {children}
65	    </AppShell>
66	  );
67	}
