input.new_string:
/* Page hero — components/ui/PageHero.tsx. A calmer, STATIC-glass treatment,
   deliberately distinct from the two motion-heavy glass effects already in
   this file: it does not spin like the AI composer's `.glow-clip-a/-b` ring,
   and it is not a full diagonal wash like `.k-wash` — a page can carry a
   PageHero AND its own `.k-wash` panel elsewhere (e.g. /dashboard/billing's
   "Add credits" card) without the two effects reading as the same thing
   twice. The frost is a translucent surface tint + backdrop-blur; the only
   ambient colour is a single contained radial tint tucked behind the icon
   corner, using the existing brand-tint tokens rather than a new hue. The
   only motion is a slow, small breathe on the icon badge — plain CSS,
   already covered by the `prefers-reduced-motion` rule below like every
   other animation on this page, so it needs no rule of its own. */
.k-hero {
  position: relative;
  overflow: hidden;
  border: 1px solid var(--border-soft);
  background: color-mix(in oklab, var(--surface) 66%, transparent);
  backdrop-filter: blur(20px) saturate(150%);
  -webkit-backdrop-filter: blur(20px) saturate(150%);
  box-shadow:
    var(--e2),
    inset 0 1px 0 color-mix(in oklab, white 14%, transparent);
}

.k-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(ellipse 60% 90% at 88% -10%, var(--brand-tint-2), transparent 70%);
}

@keyframes k-hero-icon-breathe {
  0%,
  100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.06);
  }
}
.k-hero-icon {
  animation: k-hero-icon-breathe 4.5s var(--ease-io) infinite;
}

/* Sidebar collapse. The width lives on the shell as a custom property so the
   sidebar, the mobile drawer and the main column all animate off one value
   and cannot disagree mid-transition. */

input.content:
import type { ReactNode } from "react";

/**
 * The liquid-glass page header. One shared recipe (`.k-hero` in
 * app/globals.css) for every top-level portal page, so a customer moving
 * dashboard → websites → usage → settings reads one consistent "this is the
 * top of a page" signal instead of eight ad hoc headers.
 *
 * Deliberately narrow: an icon badge, a title, a description, an optional
 * action, and an optional `children` slot for whatever real content used to
 * sit directly under that page's old plain header (stat rows, a CTA, a range
 * switcher). This component owns none of that content's behaviour — it only
 * gives it a consistent frame to sit in.
 *
 * `as` mirrors SectionHeader's own prop for the same reason: most pages using
 * this render exactly one page title, so it defaults to "h1". A page that
 * already has a real `<h1>` elsewhere must pass `as="h2"` rather than the
 * document acquiring two.
 */
export function PageHero({
  icon,
  title,
  description,
  action,
  children,
  as: Heading = "h1",
  className = "",
}: {
  icon: ReactNode;
  title: ReactNode;
  description?: ReactNode;
  action?: ReactNode;
  children?: ReactNode;
  as?: "h1" | "h2";
  className?: string;
}) {
  return (
    <section className={`k-hero rounded-2xl p-6 sm:p-8 ${className}`}>
      <div className="relative flex flex-col gap-5 sm:flex-row sm:items-start sm:justify-between">
        <div className="flex min-w-0 gap-4">
          <span
            aria-hidden
            className="k-hero-icon grid size-11 shrink-0 place-items-center rounded-xl bg-brand-tint text-brand shadow-e1 sm:size-12"
          >
            {icon}
          </span>
          <div className="min-w-0 pt-0.5">
            <Heading className="k-display text-ink">{title}</Heading>
            {description != null && (
              <p className="mt-2 max-w-2xl text-sm leading-relaxed text-ink-2">{description}</p>
            )}
          </div>
        </div>
        {action != null && <div className="relative shrink-0">{action}</div>}
      </div>
      {children != null && <div className="relative mt-5">{children}</div>}
    </section>
  );
}

