3	import Link from "next/link";
4	import { useState } from "react";
5	import { LayoutTemplate, Wand2, X } from "lucide-react";
6	import { Badge } from "@/components/ui/Badge";
7	import { Button } from "@/components/ui/Button";
8	import { useToast } from "@/components/ui/Toast";
9	import { getTemplate } from "@/lib/templates";
10	import {
11	  TemplatePickerModal,
12	  type TemplatePickerResult,
13	} from "@/components/templates/TemplatePickerModal";
14	import { InlineWizard, type InlineWizardResult } from "@/components/wizard/InlineWizard";
15	import { PromptBox } from "./PromptBox";
16	import { prepareReferenceImage } from "./image";
17	
18	export type CreditContext = {
19	  balance: number;
20	  estimate: { low: number; high: number };
21	  cap: { cap: number | null; spent: number; remaining: number | null; reached: boolean };
22	};
23	
24	/**
25	 * The one image attached to this build — from the template picker, the
26	 * wizard, OR now directly on this page via the "+" button, a paste, or a
27	 * drop onto the prompt box. Kept as `AttachedLogo`/`logo`/`onLogoChange`
28	 * rather than renamed to something like `AttachedImage`: CreateFlow.tsx (which
29	 * this file is not allowed to touch) already imports this exact shape, and
30	 * there is exactly one real attachment slot here, matching the one `image`
31	 * field app/api/generate/route.ts accepts — a rename would be cosmetic at
32	 * best and a compile break at worst. Direct attachment often is not a logo at
33	 * all (a screenshot, a product photo pasted for colour/style), so the on-page
34	 * copy below no longer calls it "your logo" — only the type name does.
35	 *
36	 * `dataUrl` is already a `data:image/(png|jpeg|webp);base64,…` — produced by
37	 * components/templates/logo.ts / components/wizard/inline-logo.ts for the two
38	 * helper flows, and by ./image.ts's prepareReferenceImage() for a direct
39	 * attachment — all three exist only to satisfy the one gate in
40	 * app/api/generate/route.ts. It travels to that route as the `image` field
41	 * and reaches the model on attempt 1 — see the note in CreateFlow.tsx for why
42	 * that, and not the brand-kit route, is where an image picked up here can
43	 * honestly go.
44	 */
45	export type AttachedLogo = { dataUrl: string; bytes: number };
46	
47	/** What a completed helper flow hands back to the page. */
48	export type AssistResult = {
49	  /** Lands in the box, editable. Nothing is ever built without a look at it. */
50	  prompt: string;
51	  logo: AttachedLogo | null;
52	  templateName: string | null;
53	};
54	
55	/** Base64 payload size, minus the `data:image/png;base64,` prefix. */
56	function dataUrlBytes(dataUrl: string): number {
57	  const comma = dataUrl.indexOf(",");
58	  return comma === -1 ? 0 : Math.round((dataUrl.length - comma - 1) * 0.75);
59	}
60	
61	/**
62	 * Make sure the palette a helper flow returned is actually IN the text.
63	 *
64	 * Both flows already write their palette into the prompt they assemble (the
65	 * `- Palette: <id> (#a to #b)` line from lib/wizard.ts and
66	 * components/templates/intake.ts), so in the normal case this changes nothing.
67	 * It exists so that a palette which for any reason did NOT make it into the
68	 * prose is folded in rather than silently dropped — the customer picked those
69	 * colours, and `palette` arriving with nowhere to go would mean it never
70	 * reached the build.
71	 *
72	 * Appended to the composer's own text, not to the request behind the
73	 * customer's back: it is then visible and editable like everything else in the
74	 * box, which is the whole rule for these hand-offs.
75	 */
76	function withPalette(prompt: string, palette: string[] | undefined): string {
77	  if (!palette || palette.length === 0) return prompt;
78	  const lower = prompt.toLowerCase();
79	  if (palette.every((hex) => lower.includes(hex.toLowerCase()))) return prompt;
80	  return `${prompt}\n\nUse these exact colours as the palette: ${palette.join(
81	    ", ",
82	  )}. Make them the dominant colours and derive everything else from those hexes — do not substitute a different palette.`;
83	}
84	
85	export function Composer({
86	  value,
87	  onChange,
88	  logo,
89	  onLogoChange,
90	  onAssist,
91	  onSubmit,
92	  fromTemplate,
93	  credits,
94	  canTopUp,
95	}: {
96	  value: string;
97	  onChange: (v: string) => void;
98	  /** Lifted to the flow so a retry after a refused build keeps the logo the
99	      customer handed over, instead of quietly dropping it. */
100	  logo: AttachedLogo | null;
101	  onLogoChange: (logo: AttachedLogo | null) => void;
102	  onAssist: (result: AssistResult) => void;
103	  onSubmit: () => void;
104	  fromTemplate: string | null;
105	  credits: CreditContext;
106	  /** False when Stripe is not configured — the billing page is still the
107	      credit ledger, but calling the link "Top up" would be a dead end. */
108	  canTopUp: boolean;
109	}) {
110	  // Both helpers open OVER this page rather than navigating to
111	  // /dashboard/templates or /wizard. Leaving the page to fetch a sentence and
112	  // coming back is the thing this replaces; the box the customer was looking
113	  // at stays where it was and simply fills in.
114	  const [pickerOpen, setPickerOpen] = useState(false);
115	  const [wizardOpen, setWizardOpen] = useState(false);
116	  const pushToast = useToast();
117	
118	  const { balance, estimate, cap } = credits;
119	  const outOfCredits = balance <= 0;
120	  const capReached = cap.reached;
121	  const tight = !outOfCredits && balance < estimate.high;
122	  const capTight = !capReached && cap.remaining !== null && cap.remaining < estimate.high;
123	
124	  const blocked = outOfCredits || capReached;
125	  const ready = value.trim().length > 0 && !blocked;
126	
127	  function acceptTemplate(result: TemplatePickerResult) {
128	    setPickerOpen(false);
129	    onAssist({
130	      prompt: withPalette(result.prompt, result.palette),
131	      logo: result.logoDataUrl
132	        ? { dataUrl: result.logoDataUrl, bytes: dataUrlBytes(result.logoDataUrl) }
133	        : null,
134	      templateName: getTemplate(result.templateId)?.name ?? null,
135	    });
136	  }
137	
138	  /**
139	   * The "+" button, a paste, and a drop onto the box all end up here — one
140	   * path so all three agree on what counts as a valid attachment.
141	   *
142	   * Video and PDF are refused HERE, before prepareReferenceImage ever runs,
143	   * with a message specific to the honest reason: there is no video-frame or
144	   * PDF-text path anywhere in this pipeline, so an "attached" video or PDF
145	   * would silently do nothing. prepareReferenceImage's own message (for a
146	   * rejected but still-an-image type, e.g. HEIC or SVG) is a different,
147	   * narrower claim — "pick a different image format" — and stays as-is.
148	   */
149	  async function attachFile(file: File, extraIgnored = 0) {
150	    if (file.type.startsWith("video/") || file.type === "application/pdf") {
151	      pushToast({
152	        tone: "danger",
153	        message:
154	          "Only images can be attached — Kodely looks at them for colour and style guidance, but has no way to read a video or PDF.",
155	      });
156	      return;
157	    }
158	
159	    const replacing = logo !== null;
160	    const result = await prepareReferenceImage(file);
161	    if (!result.ok) {
162	      pushToast({ tone: "danger", message: result.error });
163	      return;
164	    }
165	
166	    onLogoChange({ dataUrl: result.dataUrl, bytes: result.bytes });
167	
168	    // Only one image ever reaches the build, so the newest attachment always
169	    // wins — this just makes sure that's said out loud rather than the
170	    // previous thumbnail quietly vanishing with no explanation.
171	    const notes: string[] = [];
172	    if (replacing) notes.push("replaced the image you had attached");
173	    if (extraIgnored > 0) {
174	      notes.push(
175	        `only used one of the ${extraIgnored + 1} files you dropped`,
176	      );
177	    }
178	    pushToast({
179	      tone: "ok",
180	      message:
181	        notes.length > 0
182	          ? `Image attached — ${notes.join("; ")}.`
183	          : "Image attached — Kodely will look at it on the first build attempt.",
184	    });
185	  }
186	
187	  function acceptWizard(result: InlineWizardResult) {
188	    setWizardOpen(false);
189	    onAssist({
190	      prompt: withPalette(result.prompt, result.palette),
191	      logo: result.logoDataUrl
192	        ? { dataUrl: result.logoDataUrl, bytes: dataUrlBytes(result.logoDataUrl) }
193	        : null,
194	      templateName: null,
195	    });
196	  }
197	
198	  return (
199	    <div className="mx-auto w-full max-w-2xl">
200	      {/* No top padding here — the parent (CreateFlow) now centers this
201	          whole block vertically in the viewport, so extra space above it
202	          would push it off-center rather than give it room. */}
203	      <header className="text-center">
204	        <h1 className="k-display text-ink">What do you want to build?</h1>
205	        <p className="mx-auto mt-3 max-w-xl text-[0.9375rem] leading-relaxed text-ink-2">
206	          Describe it in your own words. Kodely writes a real site — React,
207	          Tailwind, your copy, as many pages as it actually needs — and you
208	          keep editing it by asking for changes.
209	        </p>
210	      </header>
211	
212	      <div className="mt-8">
213	        <PromptBox
214	          value={value}
215	          onChange={onChange}
216	          onSubmit={onSubmit}
217	          canSubmit={ready}
218	          onAttachFile={attachFile}
219	        >
220	          {(fromTemplate !== null || logo !== null) && (
221	            <div className="flex flex-col gap-2 px-6 pt-4">
222	              {fromTemplate !== null && (
223	                <div className="flex flex-wrap items-center gap-2">
224	                  <Badge tone="brand">Started from “{fromTemplate}”</Badge>
225	                  <span className="text-xs text-ink-3">
226	                    It is just text — change anything before you build.
227	                  </span>
228	                </div>
229	              )}
230	
231	              {logo !== null && (
232	                <div className="flex items-center gap-3">
233	                  {/* eslint-disable-next-line @next/next/no-img-element */}
234	                  <img
235	                    src={logo.dataUrl}
236	                    alt="The image you attached"
237	                    className="size-10 shrink-0 rounded-md border border-hair object-contain"
238	                  />
239	                  <p className="min-w-0 flex-1 text-xs leading-relaxed text-ink-3">
240	                    This image travels with this build. Kodely looks at it on the{" "}
241	                    <span className="k-num">first</span> attempt only — about{" "}
242	                    <span className="k-num">
243	                      {Math.max(1, Math.round(logo.bytes / 1024))} KB
244	                    </span>
245	                    . It is guidance for the colours and character, not a file that gets
246	                    uploaded; the brief above says what to do with the space it belongs in.
247	                  </p>
248	                  <Button
249	                    variant="ghost"
250	                    size="sm"
251	                    icon={<X size={14} />}
252	                    onClick={() => onLogoChange(null)}
253	                  >
254	                    Remove
255	                  </Button>
256	                </div>
257	              )}
258	            </div>
259	          )}
260	        </PromptBox>
261	      </div>
262	
263	      {/* The two side doors, below the box rather than beside it: the raw box
264	          stays the default, and neither helper is ever a gate. Both open in
265	          place and both hand their text back into the box above, editable —
266	          nothing is built until the customer presses the button themselves. */}
267	      <div className="mt-4 flex flex-wrap items-center justify-center gap-2">
268	        <AssistChip icon={<LayoutTemplate size={14} />} onClick={() => setPickerOpen(true)}>
269	          Use a template
270	        </AssistChip>
271	        <AssistChip icon={<Wand2 size={14} />} onClick={() => setWizardOpen(true)}>
272	          Help me write it
273	        </AssistChip>
274	      </div>
275	
276	      <div className="mt-8">
277	        <CreditNote
278	          balance={balance}
279	          outOfCredits={outOfCredits}
280	          tight={tight}
281	          cap={cap}
282	          capReached={capReached}
283	          capTight={capTight}
284	          canTopUp={canTopUp}
285	        />
286	      </div>
287	
288	      <TemplatePickerModal
289	        open={pickerOpen}
290	        onClose={() => setPickerOpen(false)}
291	        onComplete={acceptTemplate}
292	      />
293	      <InlineWizard
294	        open={wizardOpen}
295	        onClose={() => setWizardOpen(false)}
296	        onComplete={acceptWizard}
297	      />
298	    </div>
299	  );
300	}
301	
302	function AssistChip({
303	  icon,
304	  onClick,
305	  children,
306	}: {
307	  icon: React.ReactNode;
308	  onClick: () => void;
309	  children: React.ReactNode;
310	}) {
311	  return (
312	    <button
313	      type="button"
314	      onClick={onClick}
315	      className="k-focus inline-flex items-center gap-1.5 rounded-full border border-hair bg-surface px-3.5 py-1.5 text-xs font-medium text-ink-2 shadow-e1 transition-[color,border-color,background] duration-[var(--t-1)] hover:border-line-mid hover:bg-surface-2 hover:text-ink"
316	    >
317	      <span className="text-ink-3" aria-hidden>
318	        {icon}
319	      </span>
320	      {children}
321	    </button>
322	  );
323	}
324	
325	function CreditNote({
326	  balance,
327	  outOfCredits,
328	  tight,
329	  cap,
330	  capReached,
331	  capTight,
332	  canTopUp,
333	}: {
334	  balance: number;
335	  outOfCredits: boolean;
336	  tight: boolean;
337	  cap: CreditContext["cap"];
338	  capReached: boolean;
339	  capTight: boolean;
340	  canTopUp: boolean;
341	}) {
342	  return (
343	    <div className="rounded-xl border border-hair bg-surface-2/60 p-4">
344	      <p className="text-[0.8125rem] text-ink-2">
345	        You have <span className="k-num font-semibold text-ink">{balance}</span> credits
346	      </p>
347	
348	      <p className="mt-2 text-xs leading-relaxed text-ink-3">
349	        You are charged only for the attempt you asked for. If the first output doesn’t compile,
350	        Kodely’s repair pass is on us, and a build that fails outright costs you nothing.
351	      </p>
352	
353	      {outOfCredits && (
354	        <Callout tone="danger">
355	          You’re out of credits, so a build would be refused before it started.
356	          {canTopUp ? " Top up and this brief will still be here." : " Top-ups are unavailable right now."}
357	          <CalloutAction
358	            href="/dashboard/billing"
359	            label={canTopUp ? "Top up credits" : "See your credit ledger"}
360	          />
361	        </Callout>
362	      )}
363	
364	      {tight && (
365	        <Callout tone="warn">
366	          That’s below what a first build usually costs. Your balance is checked when a build
367	          starts, not while it runs — so this one can finish and take you to zero or below.
368	          <CalloutAction
369	            href="/dashboard/billing"
370	            label={canTopUp ? "Top up first" : "See your credit ledger"}
371	          />
372	        </Callout>
373	      )}
374	
375	      {capReached && cap.cap !== null && (
376	        <Callout tone="danger">
377	          You’ve hit the spending cap you set — <span className="k-num">{cap.spent}</span> of{" "}
378	          <span className="k-num">{cap.cap}</span> credits in the last 30 days. Builds are refused
379	          until you raise or remove it.
380	          <CalloutAction href="/settings/credits" label="Change your cap" />
381	        </Callout>
382	      )}
383	
384	      {capTight && cap.remaining !== null && (
385	        <Callout tone="warn">
386	          Your own spending cap leaves <span className="k-num">{cap.remaining}</span> credits in
387	          this 30-day window, which may not cover a full build.
388	          <CalloutAction href="/settings/credits" label="Review your cap" />
389	        </Callout>
390	      )}
391	    </div>
392	  );
393	}
394	
395	function Callout({ tone, children }: { tone: "warn" | "danger"; children: React.ReactNode }) {
396	  const skin =
397	    tone === "danger"
398	      ? "border-danger/25 bg-danger-tint text-danger"
399	      : "border-warn/25 bg-warn-tint text-warn";
400	  return (
401	    <p
402	      className={`mt-3 flex flex-wrap items-center gap-x-2 gap-y-1 rounded-lg border px-3 py-2 text-xs leading-relaxed ${skin}`}
403	    >
404	      {children}
405	    </p>
406	  );
407	}
408	
409	function CalloutAction({ href, label }: { href: string; label: string }) {
410	  return (
411	    <Link
412	      href={href}
413	      className="k-focus rounded-xs font-semibold underline underline-offset-2"
414	    >
415	      {label}
416	    </Link>
417	  );
418	}
