1	"use client";
2	
3	import Link from "next/link";
4	import { useState } from "react";
5	import { Hammer, LayoutTemplate, Wand2, X } from "lucide-react";
6	import { Badge } from "@/components/ui/Badge";
7	import { Button } from "@/components/ui/Button";
8	import { PageHero } from "@/components/ui/PageHero";
9	import { useToast } from "@/components/ui/Toast";
10	import { getTemplate } from "@/lib/templates";
11	import {
12	  TemplatePickerModal,
13	  type TemplatePickerResult,
14	} from "@/components/templates/TemplatePickerModal";
15	import { InlineWizard, type InlineWizardResult } from "@/components/wizard/InlineWizard";
16	import { PromptBox } from "./PromptBox";
17	import {
18	  ACCEPTED_VIDEO_TYPES,
19	  PDF_TYPE,
20	  extractVideoFirstFrame,
21	  prepareReferenceDocument,
22	  prepareReferenceImage,
23	} from "./attachment";
24	
25	export type CreditContext = {
26	  balance: number;
27	  estimate: { low: number; high: number };
28	  cap: { cap: number | null; spent: number; remaining: number | null; reached: boolean };
29	};
30	
31	/**
32	 * The one IMAGE attached to this build — from the template picker, the
33	 * wizard, directly on this page via the "+" button/paste/drop, OR now as the
34	 * first-frame extraction of a directly-attached video (see attachFile below).
35	 * Kept as `AttachedLogo`/`logo`/`onLogoChange` rather than renamed to
36	 * something like `AttachedImage`: CreateFlow.tsx already imports this exact
37	 * shape, and a rename would be cosmetic at best and a compile break at worst.
38	 * Direct attachment often is not a logo at all (a screenshot, a product photo,
39	 * a video's first frame pasted for colour/style), so the on-page copy below
40	 * no longer calls it "your logo" — only the type name does.
41	 *
42	 * `dataUrl` is already a `data:image/(png|jpeg|webp);base64,…` — produced by
43	 * components/templates/logo.ts / components/wizard/inline-logo.ts for the two
44	 * helper flows, and by ./attachment.ts's prepareReferenceImage() (directly, or
45	 * via extractVideoFirstFrame()) for a direct attachment. It travels to
46	 * app/api/generate/route.ts as the `image` field and reaches the model on
47	 * attempt 1 — see the note in CreateFlow.tsx for why that, and not the
48	 * brand-kit route, is where an image picked up here can honestly go.
49	 *
50	 * This and `AttachedDocument` right below are mutually exclusive: there is
51	 * exactly one reference-file slot on this page, and it holds either an image
52	 * (or a video's extracted frame, which IS an image by the time it reaches
53	 * this type) or a PDF, never both — see attachFile's onLogoChange(null) /
54	 * onDocumentChange(null) pairing.
55	 */
56	export type AttachedLogo = { dataUrl: string; bytes: number };
57	
58	/**
59	 * The one PDF attached to this build — the second, newer half of the same
60	 * single reference-file slot `AttachedLogo` describes above. `dataUrl` is
61	 * `data:application/pdf;base64,…`, produced by ./attachment.ts's
62	 * prepareReferenceDocument(). It travels to app/api/generate/route.ts as the
63	 * new `document` field, gated to attempt 1 exactly like `image` — see
64	 * lib/agent.ts's message construction for both.
65	 */
66	export type AttachedDocument = { dataUrl: string; bytes: number; name: string };
67	
68	/** What a completed helper flow hands back to the page. */
69	export type AssistResult = {
70	  /** Lands in the box, editable. Nothing is ever built without a look at it. */
71	  prompt: string;
72	  logo: AttachedLogo | null;
73	  templateName: string | null;
74	};
75	
76	/** Base64 payload size, minus the `data:image/png;base64,` prefix. */
77	function dataUrlBytes(dataUrl: string): number {
78	  const comma = dataUrl.indexOf(",");
79	  return comma === -1 ? 0 : Math.round((dataUrl.length - comma - 1) * 0.75);
80	}
81	
82	/**
83	 * Make sure the palette a helper flow returned is actually IN the text.
84	 *
85	 * Both flows already write their palette into the prompt they assemble (the
86	 * `- Palette: <id> (#a to #b)` line from lib/wizard.ts and
87	 * components/templates/intake.ts), so in the normal case this changes nothing.
88	 * It exists so that a palette which for any reason did NOT make it into the
89	 * prose is folded in rather than silently dropped — the customer picked those
90	 * colours, and `palette` arriving with nowhere to go would mean it never
91	 * reached the build.
92	 *
93	 * Appended to the composer's own text, not to the request behind the
94	 * customer's back: it is then visible and editable like everything else in the
95	 * box, which is the whole rule for these hand-offs.
96	 */
97	function withPalette(prompt: string, palette: string[] | undefined): string {
98	  if (!palette || palette.length === 0) return prompt;
99	  const lower = prompt.toLowerCase();
100	  if (palette.every((hex) => lower.includes(hex.toLowerCase()))) return prompt;
101	  return `${prompt}\n\nUse these exact colours as the palette: ${palette.join(
102	    ", ",
103	  )}. Make them the dominant colours and derive everything else from those hexes — do not substitute a different palette.`;
104	}
105	
106	export function Composer({
107	  value,
108	  onChange,
109	  logo,
110	  onLogoChange,
111	  onAssist,
112	  onSubmit,
113	  fromTemplate,
114	  credits,
115	  canTopUp,
116	}: {
117	  value: string;
118	  onChange: (v: string) => void;
119	  /** Lifted to the flow so a retry after a refused build keeps the logo the
120	      customer handed over, instead of quietly dropping it. */
121	  logo: AttachedLogo | null;
122	  onLogoChange: (logo: AttachedLogo | null) => void;
123	  onAssist: (result: AssistResult) => void;
124	  onSubmit: () => void;
125	  fromTemplate: string | null;
126	  credits: CreditContext;
127	  /** False when Stripe is not configured — the billing page is still the
128	      credit ledger, but calling the link "Top up" would be a dead end. */
129	  canTopUp: boolean;
130	}) {
131	  // Both helpers open OVER this page rather than navigating to
132	  // /dashboard/templates or /wizard. Leaving the page to fetch a sentence and
133	  // coming back is the thing this replaces; the box the customer was looking
134	  // at stays where it was and simply fills in.
135	  const [pickerOpen, setPickerOpen] = useState(false);
136	  const [wizardOpen, setWizardOpen] = useState(false);
137	  const pushToast = useToast();
138	
139	  const { balance, estimate, cap } = credits;
140	  const outOfCredits = balance <= 0;
141	  const capReached = cap.reached;
142	  const tight = !outOfCredits && balance < estimate.high;
143	  const capTight = !capReached && cap.remaining !== null && cap.remaining < estimate.high;
144	
145	  const blocked = outOfCredits || capReached;
146	  const ready = value.trim().length > 0 && !blocked;
147	
148	  function acceptTemplate(result: TemplatePickerResult) {
149	    setPickerOpen(false);
150	    onAssist({
151	      prompt: withPalette(result.prompt, result.palette),
152	      logo: result.logoDataUrl
153	        ? { dataUrl: result.logoDataUrl, bytes: dataUrlBytes(result.logoDataUrl) }
154	        : null,
155	      templateName: getTemplate(result.templateId)?.name ?? null,
156	    });
157	  }
158	
159	  /**
160	   * The "+" button, a paste, and a drop onto the box all end up here — one
161	   * path so all three agree on what counts as a valid attachment.
162	   *
163	   * Video and PDF are refused HERE, before prepareReferenceImage ever runs,
164	   * with a message specific to the honest reason: there is no video-frame or
165	   * PDF-text path anywhere in this pipeline, so an "attached" video or PDF
166	   * would silently do nothing. prepareReferenceImage's own message (for a
167	   * rejected but still-an-image type, e.g. HEIC or SVG) is a different,
168	   * narrower claim — "pick a different image format" — and stays as-is.
169	   */
170	  async function attachFile(file: File, extraIgnored = 0) {
171	    if (file.type.startsWith("video/") || file.type === "application/pdf") {
172	      pushToast({
173	        tone: "danger",
174	        message:
175	          "Only images can be attached — Kodely looks at them for colour and style guidance, but has no way to read a video or PDF.",
176	      });
177	      return;
178	    }
179	
180	    const replacing = logo !== null;
181	    const result = await prepareReferenceImage(file);
182	    if (!result.ok) {
183	      pushToast({ tone: "danger", message: result.error });
184	      return;
185	    }
186	
187	    onLogoChange({ dataUrl: result.dataUrl, bytes: result.bytes });
188	
189	    // Only one image ever reaches the build, so the newest attachment always
190	    // wins — this just makes sure that's said out loud rather than the
191	    // previous thumbnail quietly vanishing with no explanation.
192	    const notes: string[] = [];
193	    if (replacing) notes.push("replaced the image you had attached");
194	    if (extraIgnored > 0) {
195	      notes.push(
196	        `only used one of the ${extraIgnored + 1} files you dropped`,
197	      );
198	    }
199	    pushToast({
200	      tone: "ok",
201	      message:
202	        notes.length > 0
203	          ? `Image attached — ${notes.join("; ")}.`
204	          : "Image attached — Kodely will look at it on the first build attempt.",
205	    });
206	  }
207	
208	  function acceptWizard(result: InlineWizardResult) {
209	    setWizardOpen(false);
210	    onAssist({
211	      prompt: withPalette(result.prompt, result.palette),
212	      logo: result.logoDataUrl
213	        ? { dataUrl: result.logoDataUrl, bytes: dataUrlBytes(result.logoDataUrl) }
214	        : null,
215	      templateName: null,
216	    });
217	  }
218	
219	  return (
220	    <div className="mx-auto w-full max-w-2xl">
221	      {/* No top margin here — the parent (CreateFlow) now centers this
222	          whole block vertically in the viewport, so extra space above it
223	          would push it off-center rather than give it room. */}
224	      <PageHero
225	        icon={<Hammer className="size-5" aria-hidden />}
226	        title="What do you want to build?"
227	        description="Describe it in your own words. Kodely writes a real site — React, Tailwind, your copy, as many pages as it actually needs — and you keep editing it by asking for changes."
228	      />
229	
230	      <div className="mt-8">
231	        <PromptBox
232	          value={value}
233	          onChange={onChange}
234	          onSubmit={onSubmit}
235	          canSubmit={ready}
236	          onAttachFile={attachFile}
237	        >
238	          {(fromTemplate !== null || logo !== null) && (
239	            <div className="flex flex-col gap-2 px-6 pt-4">
240	              {fromTemplate !== null && (
241	                <div className="flex flex-wrap items-center gap-2">
242	                  <Badge tone="brand">Started from “{fromTemplate}”</Badge>
243	                  <span className="text-xs text-ink-3">
244	                    It is just text — change anything before you build.
245	                  </span>
246	                </div>
247	              )}
248	
249	              {logo !== null && (
250	                <div className="flex items-center gap-3">
251	                  {/* eslint-disable-next-line @next/next/no-img-element */}
252	                  <img
253	                    src={logo.dataUrl}
254	                    alt="The image you attached"
255	                    className="size-10 shrink-0 rounded-md border border-hair object-contain"
256	                  />
257	                  <p className="min-w-0 flex-1 text-xs leading-relaxed text-ink-3">
258	                    This image travels with this build. Kodely looks at it on the{" "}
259	                    <span className="k-num">first</span> attempt only — about{" "}
260	                    <span className="k-num">
261	                      {Math.max(1, Math.round(logo.bytes / 1024))} KB
262	                    </span>
263	                    . It is guidance for the colours and character, not a file that gets
264	                    uploaded; the brief above says what to do with the space it belongs in.
265	                  </p>
266	                  <Button
267	                    variant="ghost"
268	                    size="sm"
269	                    icon={<X size={14} />}
270	                    onClick={() => onLogoChange(null)}
271	                  >
272	                    Remove
273	                  </Button>
274	                </div>
275	              )}
276	            </div>
277	          )}
278	        </PromptBox>
279	      </div>
280	
281	      {/* The two side doors, below the box rather than beside it: the raw box
282	          stays the default, and neither helper is ever a gate. Both open in
283	          place and both hand their text back into the box above, editable —
284	          nothing is built until the customer presses the button themselves. */}
285	      <div className="mt-4 flex flex-wrap items-center justify-center gap-2">
286	        <AssistChip icon={<LayoutTemplate size={14} />} onClick={() => setPickerOpen(true)}>
287	          Use a template
288	        </AssistChip>
289	        <AssistChip icon={<Wand2 size={14} />} onClick={() => setWizardOpen(true)}>
290	          Help me write it
291	        </AssistChip>
292	      </div>
293	
294	      <div className="mt-8">
295	        <CreditNote
296	          balance={balance}
297	          outOfCredits={outOfCredits}
298	          tight={tight}
299	          cap={cap}
300	          capReached={capReached}
301	          capTight={capTight}
302	          canTopUp={canTopUp}
303	        />
304	      </div>
305	
306	      <TemplatePickerModal
307	        open={pickerOpen}
308	        onClose={() => setPickerOpen(false)}
309	        onComplete={acceptTemplate}
310	      />
311	      <InlineWizard
312	        open={wizardOpen}
313	        onClose={() => setWizardOpen(false)}
314	        onComplete={acceptWizard}
315	      />
316	    </div>
317	  );
318	}
319	
320	function AssistChip({
321	  icon,
322	  onClick,
323	  children,
324	}: {
325	  icon: React.ReactNode;
326	  onClick: () => void;
327	  children: React.ReactNode;
328	}) {
329	  return (
330	    <button
331	      type="button"
332	      onClick={onClick}
333	      className="k-focus inline-flex items-center gap-1.5 rounded-full border border-hair bg-surface px-3.5 py-1.5 text-xs font-medium text-ink-2 shadow-e1 transition-[color,border-color,background] duration-[var(--t-1)] hover:border-line-mid hover:bg-surface-2 hover:text-ink"
334	    >
335	      <span className="text-ink-3" aria-hidden>
336	        {icon}
337	      </span>
338	      {children}
339	    </button>
340	  );
341	}
342	
343	function CreditNote({
344	  balance,
345	  outOfCredits,
346	  tight,
347	  cap,
348	  capReached,
349	  capTight,
350	  canTopUp,
351	}: {
352	  balance: number;
353	  outOfCredits: boolean;
354	  tight: boolean;
355	  cap: CreditContext["cap"];
356	  capReached: boolean;
357	  capTight: boolean;
358	  canTopUp: boolean;
359	}) {
360	  return (
361	    <div className="rounded-xl border border-hair bg-surface-2/60 p-4">
362	      <p className="text-[0.8125rem] text-ink-2">
363	        You have <span className="k-num font-semibold text-ink">{balance}</span> credits
364	      </p>
365	
366	      <p className="mt-2 text-xs leading-relaxed text-ink-3">
367	        You are charged only for the attempt you asked for. If the first output doesn’t compile,
368	        Kodely’s repair pass is on us, and a build that fails outright costs you nothing.
369	      </p>
370	
371	      {outOfCredits && (
372	        <Callout tone="danger">
373	          You’re out of credits, so a build would be refused before it started.
374	          {canTopUp ? " Top up and this brief will still be here." : " Top-ups are unavailable right now."}
375	          <CalloutAction
376	            href="/dashboard/billing"
377	            label={canTopUp ? "Top up credits" : "See your credit ledger"}
378	          />
379	        </Callout>
380	      )}
381	
382	      {tight && (
383	        <Callout tone="warn">
384	          That’s below what a first build usually costs. Your balance is checked when a build
385	          starts, not while it runs — so this one can finish and take you to zero or below.
386	          <CalloutAction
387	            href="/dashboard/billing"
388	            label={canTopUp ? "Top up first" : "See your credit ledger"}
389	          />
390	        </Callout>
391	      )}
392	
393	      {capReached && cap.cap !== null && (
394	        <Callout tone="danger">
395	          You’ve hit the spending cap you set — <span className="k-num">{cap.spent}</span> of{" "}
396	          <span className="k-num">{cap.cap}</span> credits in the last 30 days. Builds are refused
397	          until you raise or remove it.
398	          <CalloutAction href="/settings/credits" label="Change your cap" />
399	        </Callout>
400	      )}
401	
402	      {capTight && cap.remaining !== null && (
403	        <Callout tone="warn">
404	          Your own spending cap leaves <span className="k-num">{cap.remaining}</span> credits in
405	          this 30-day window, which may not cover a full build.
406	          <CalloutAction href="/settings/credits" label="Review your cap" />
407	        </Callout>
408	      )}
409	    </div>
410	  );
411	}
412	
413	function Callout({ tone, children }: { tone: "warn" | "danger"; children: React.ReactNode }) {
414	  const skin =
415	    tone === "danger"
416	      ? "border-danger/25 bg-danger-tint text-danger"
417	      : "border-warn/25 bg-warn-tint text-warn";
418	  return (
419	    <p
420	      className={`mt-3 flex flex-wrap items-center gap-x-2 gap-y-1 rounded-lg border px-3 py-2 text-xs leading-relaxed ${skin}`}
421	    >
422	      {children}
423	    </p>
424	  );
425	}
426	
427	function CalloutAction({ href, label }: { href: string; label: string }) {
428	  return (
429	    <Link
430	      href={href}
431	      className="k-focus rounded-xs font-semibold underline underline-offset-2"
432	    >
433	      {label}
434	    </Link>
435	  );
436	}
