1	"use client";
2	
3	import Link from "next/link";
4	import { usePathname } from "next/navigation";
5	import { CreditCard, ShieldCheck, UserRound } from "lucide-react";
6	import type { LucideIcon } from "lucide-react";
7	
8	/* WHY REAL ROUTES AND NOT A CLIENT TAB COMPONENT
9	   ─────────────────────────────────────────────
10	   Each section is a Server Component with its own queries, and they are not
11	   cheap ones: Security counts and lists sessions and computes the deletion
12	   preview (eleven counts across nine tables), Credits aggregates 30 days of
13	   the ledger. A single page with client-side tabs would run all of that on
14	   every visit to Settings, to render one panel.
15	
16	   Three more things fall out of using the router rather than useState:
17	   a section is linkable and survives a reload (the Discord OAuth callback
18	   redirects to /settings with an outcome in the query string, and it has to
19	   land somewhere specific); Back does what it looks like it does; and the
20	   only client JavaScript on the Account tab is the name field itself.
21	
22	   This component is a Client Component solely to read the pathname for the
23	   active state — it holds no state of its own. */
24	
25	type Tab = { href: string; label: string; icon: LucideIcon; exact?: boolean };
26	
27	const TABS: Tab[] = [
28	  { href: "/settings", label: "Account", icon: UserRound, exact: true },
29	  { href: "/settings/credits", label: "Credits", icon: CreditCard },
30	  { href: "/settings/security", label: "Security", icon: ShieldCheck },
31	];
32	
33	export default function SettingsNav() {
34	  const pathname = usePathname();
35	
36	  return (
37	    <nav aria-label="Settings sections" className="k-scroll-x -mx-1 px-1">
38	      <ul className="flex min-w-max items-center gap-1 border-b border-hair pb-px">
39	        {TABS.map((tab) => {
40	          const active = tab.exact ? pathname === tab.href : pathname.startsWith(tab.href);
41	          const Icon = tab.icon;
42	          return (
43	            <li key={tab.href}>
44	              <Link
45	                href={tab.href}
46	                aria-current={active ? "page" : undefined}
47	                className={[
48	                  "k-focus relative -mb-px inline-flex items-center gap-2 rounded-t-md px-3 py-2.5 text-sm font-medium",
49	                  "border-b-2 transition-colors duration-[var(--t-1)]",
50	                  active
51	                    ? "border-brand text-ink"
52	                    : "border-transparent text-ink-2 hover:border-line-mid hover:text-ink",
53	                ].join(" ")}
54	              >
55	                <Icon className="size-4" aria-hidden />
56	                {tab.label}
57	              </Link>
58	            </li>
59	          );
60	        })}
61	      </ul>
62	    </nav>
63	  );
64	}
